insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-matematika-sma-001', 'sub-matematika-sma', 'top-matematika-sma-01', null, 'single', 'Memahami, mengaplikasikan, dan bernalar yang lebih tinggi untuk menyelesaikan permasalahan terkait sistem persamaan linear multivariabel', 'html', null, '<p>Harga 3 buah buku dan 2 buah penggaris Rp18.000,00. Jika harga sebuah buku Rp1.000,00 lebih mahal dari sebuah penggaris, harga 2 buah buku dan 5 buah penggaris adalah ....</p>', null, '[{"key":"A","text":"<p>Rp19.000,00</p>"},{"key":"B","text":"<p>Rp23.000,00</p>"},{"key":"C","text":"<p>Rp25.000,00</p>"},{"key":"D","text":"<p>Rp27.000,00</p>"},{"key":"E","text":"<p>Rp30.000,00</p>"}]'::jsonb, 'B', null, null, null, 'B') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-matematika-sma-002', 'sub-matematika-sma', 'top-matematika-sma-02', null, 'single', 'Memahami, mengaplikasikan, dan bernalar yang lebih tinggi untuk menyelesaikan permasalahan terkait sistem pertidaksamaan linear multivariabel', 'html', null, '<p>Perhatikan gambar berikut.</p><p><img src="/soal/88819_6837a3202add4799943b1f2837c58003.png" alt=""/></p><p>Daerah yang memenuhi sistem pertidaksamaan linear <img src="/soal/95089_d25340b2a7ed58e850e0298630c96c79.png" alt=""/> adalah ....</p>', null, '[{"key":"A","text":"<p>I</p>"},{"key":"B","text":"<p>II</p>"},{"key":"C","text":"<p>III</p>"},{"key":"D","text":"<p>IV</p>"},{"key":"E","text":"<p>V</p>"}]'::jsonb, 'B', null, null, null, 'B') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-matematika-sma-003', 'sub-matematika-sma', 'top-matematika-sma-03', null, 'single', 'Memahami, mengaplikasikan, dan bernalar yang lebih tinggi untuk menyelesaikan permasalahan terkait invers fungsi dan representasinya', 'html', null, '<p>Diketahui fungsi <em>f</em>(<em>x</em>) = <img src="/soal/90318_c60ef3ace5c263099625b4010816a4d6.png" alt=""/> , dengan <img src="/soal/90318_2a36cdc3b7f69c96b64c46de15d93cba.png" alt=""/> . Jika <em>f </em><sup>–1</sup>(<em>x</em>) adalah invers dari fungsi <em>f</em>(<em>x</em>), nilai dari <em>f </em><sup>–1</sup>(3) = ....</p>', null, '[{"key":"A","text":"<p>6</p>"},{"key":"B","text":"<p>3</p>"},{"key":"C","text":"<p><img src=\"/soal/90318_46f958d9049ce63426b88d5d95566247.png\" alt=\"\"/></p>"},{"key":"D","text":"<p><img src=\"/soal/90318_0023d56d4147d6d42f218fe65a9239a3.png\" alt=\"\"/></p>"},{"key":"E","text":"<p>-1</p>"}]'::jsonb, 'B', null, null, null, 'B') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-matematika-sma-004', 'sub-matematika-sma', 'top-matematika-sma-04', null, 'single', 'Memahami, mengaplikasikan, dan bernalar yang lebih tinggi untuk menyelesaikan permasalahan terkait fungsi komposisi dan representasinya', 'html', null, '<p>Fungsi <em>f : R -&gt; R</em> dan <em>g R -&gt; R </em>. Jika <em>g</em><em>(x) = x - 1</em> dan (<em>f o</em><em></em><em>g</em>)<em>(x) = x<sup>3 </sup>– 4x</em>, nilai dari <em>f</em>(2) = ….</p>', null, '[{"key":"A","text":"<p>9</p>"},{"key":"B","text":"<p>13</p>"},{"key":"C","text":"<p>15</p>"},{"key":"D","text":"<p>17</p>"},{"key":"E","text":"<p>25</p>"}]'::jsonb, 'C', null, null, null, 'C') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-matematika-sma-005', 'sub-matematika-sma', 'top-matematika-sma-05', null, 'single', 'Memahami, mengaplikasikan, dan bernalar yang lebih tinggi untuk menyelesaikan permasalahan terkait barisan dan deret geometri.', 'html', null, '<p>Seorang peneliti melakukan pengamatan terhadap bakteri tertentu. Setiap <img src="/soal/67173_421b5ddd9a615c99017cadb0f23594f5.png" alt=""/> hari bakteri membelah diri menjadi dua. Pada awal pengamatan terdapat 2 bakteri. Jika setiap 2 hari <img src="/soal/67173_7d34d2ec1b5adb5d52018be3dd4f536b.png" alt=""/> dari jumlah bakteri mati, banyaknya bakteri setelah tiga hari adalah....</p>', null, '[{"key":"A","text":"<p>48 bakteri</p>"},{"key":"B","text":"<p>64 bakteri</p>"},{"key":"C","text":"<p>96 bakteri</p>"},{"key":"D","text":"<p>128 bakteri</p>"},{"key":"E","text":"<p>192 bakteri</p>"}]'::jsonb, 'C', null, null, null, 'C') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-matematika-sma-006', 'sub-matematika-sma', 'top-matematika-sma-06', null, 'single', 'Memahami, mengaplikasikan, dan bernalar yang lebih tinggi untuk menyelesaikan permasalahan terkait volume dan luas permukaan bangun ruang.', 'html', null, '<p>Dari selembar karton berbentuk persegi yang berukuran sisi 30 cm akan dibuat kotak tanpa tutup, dengan cara menggunting empat persegi di setiap pojok karton, seperti pada gambar. Volume kotak terbesar yang dapat dibuat adalah ....</p><p><img src="/soal/62193_925f43a370cc2bcce192c20158ee0776.png" alt=""/></p>', null, '[{"key":"A","text":"<p>2.000 cm³</p>"},{"key":"B","text":"<p>3.000 cm³</p>"},{"key":"C","text":"<p>4.000 cm³</p>"},{"key":"D","text":"<p>5.000 cm³</p>"},{"key":"E","text":"<p>6.000 cm³</p>"}]'::jsonb, 'A', null, null, null, 'A') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-matematika-sma-007', 'sub-matematika-sma', 'top-matematika-sma-07', null, 'single', 'Memahami, mengaplikasikan, dan bernalar yang lebih tinggi untuk menyelesaikan permasalahan terkait perbandingan trigonometri (sinus, kosinus, tangen, kotangen, sekan, kosekan).', 'html', null, '<p>Diketahui sin A = <img src="/soal/40142_b2b0e90fe3a7fb9c6dac4483037e80f8.png" alt=""/> , A adalah sudut tumpul. Nilai cos A = ….</p>', null, '[{"key":"A","text":"<p><img src=\"/soal/40142_8f89379a74f84bb7135a6a4cfe93efe8.png\" alt=\"\"/></p>"},{"key":"B","text":"<p><img src=\"/soal/40142_90283f302d3db0e305be26ebf7774d94.png\" alt=\"\"/></p>"},{"key":"C","text":"<p><img src=\"/soal/40142_8c51847f8f3cffa26b1b63abeb79ad05.png\" alt=\"\"/></p>"},{"key":"D","text":"<p><img src=\"/soal/40142_8b77a789f8a25d8af19266963c579ec3.png\" alt=\"\"/></p>"},{"key":"E","text":"<p><img src=\"/soal/40142_672a861796e5d4bc135fbc5a1b282873.png\" alt=\"\"/></p>"}]'::jsonb, 'D', null, null, null, 'D') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-matematika-sma-008', 'sub-matematika-sma', 'top-matematika-sma-08', null, 'single', 'Memahami, mengaplikasikan, dan bernalar yang lebih tinggi untuk menyelesaikan permasalahan terkait penyajian data dalam bentuk diagram batang, diagram garis, diagram lingkaran, grafik, tabel, dan bentuk visual', 'html', null, '<p>Diagram batang berikut menunjukkan produksi pakaian yang dikelola Bu Rahmi selama tahun 2020 dari bulan Januari sampai bulan Desember.</p><p><img src="/soal/20035_8290fb5c5d179db0ca8d6f0a8a445d0d.png" alt=""/></p><p>Peningkatan tertinggi jumlah produksi pakaian Bu Rahmi terjadi pada bulan ....</p>', null, '[{"key":"A","text":"<p>April</p>"},{"key":"B","text":"<p>Juni</p>"},{"key":"C","text":"<p>Juli</p>"},{"key":"D","text":"<p>September</p>"},{"key":"E","text":"<p>November</p>"}]'::jsonb, 'E', null, null, null, 'E') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-matematika-sma-009', 'sub-matematika-sma', 'top-matematika-sma-09', null, 'single', 'Memahami, mengaplikasikan, dan bernalar yang lebih tinggi untuk menyelesaikan permasalahan terkait ukuran pemusatan dan penyebaran data tunggal dan data kelompok', 'html', null, '<p>Perhatikan data pada tabel nilai hasil ulangan matematika kelas XI SMA Z. Modus dari data tersebut adalah ....</p><p><img src="/soal/17865_03efca3015969271cc01dd691c5df6f3.png" alt=""/></p>', null, '[{"key":"A","text":"<p>64,0</p>"},{"key":"B","text":"<p>64,5</p>"},{"key":"C","text":"<p>65,0</p>"},{"key":"D","text":"<p>65,5</p>"},{"key":"E","text":"<p>66,0</p>"}]'::jsonb, 'C', null, null, null, 'C') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-matematika-sma-010', 'sub-matematika-sma', 'top-matematika-sma-10', null, 'single', 'Memahami, mengaplikasikan, dan bernalar yang lebih tinggi untuk menyelesaikan permasalahan terkait peluang suatu kejadian majemuk', 'html', null, '<p>Sekolah P akan mengirim 2 perwakilan grup band untuk Pentas Musik Nusantara pada peringatan Hari Sumpah Pemuda. Sekolah tersebut memiliki 6 grup band putra dan 4 grup band putri. Berdasarkan penilaian, kemampuan grup band tersebut merata sehingga penentuan kedua perwakilan grup band dilakukan dengan cara mengambil secara acak satu persatu. Peluang terambil grup band putra pada pengambilan pertama dan grup band putri pada pengambilan kedua adalah ....</p>', null, '[{"key":"A","text":"<p><img src=\"/soal/93353_ba88e2a4dfbcc2652503c8b70fa7d0eb.png\" alt=\"\"/></p>"},{"key":"B","text":"<p><img src=\"/soal/93353_074491fe27246e89aa2eac2f8bcf31f8.png\" alt=\"\"/></p>"},{"key":"C","text":"<p><img src=\"/soal/93353_139a68813cbdea07eca780390d59ed63.png\" alt=\"\"/></p>"},{"key":"D","text":"<p><img src=\"/soal/93353_360ffa720383cf957b4e69cdf09e26b3.png\" alt=\"\"/></p>"},{"key":"E","text":"<p><img src=\"/soal/93353_8487725a4d4d086db474b71486a60fe6.png\" alt=\"\"/></p>"}]'::jsonb, 'C', null, null, null, 'C') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-matematika-sma-011', 'sub-matematika-sma', 'top-matematika-sma-11', 'st-matematika-sma-01', 'single', 'Memahami, mengaplikasikan, dan bernalar yang lebih tinggi untuk menyelesaikan permasalahan terkait operasi bilangan (penjumlahan, pengurangan, perkalian, pembagian, dan gabungannya), beserta sifat-si', 'html', null, '<p><img src="/soal/13733_f5d65862b7fd46841091085827fb3783.png" alt=""/></p>', null, '[{"key":"A","text":"<p><img src=\"/soal/56549_a3d3e4919f37d1b31d8095fa8e333a1f.png\" alt=\"\"/></p>"},{"key":"B","text":"<p><img src=\"/soal/56549_030dce7f7746acd4bc4b471c044542b8.png\" alt=\"\"/></p>"},{"key":"C","text":"<p><img src=\"/soal/56549_db302896bfc802d93220fbace3a48da1.png\" alt=\"\"/></p>"},{"key":"D","text":"<p><img src=\"/soal/56549_44e708f4b28ce9544fcfdb048c866712.png\" alt=\"\"/></p>"},{"key":"E","text":"<p><img src=\"/soal/56549_6f0950c1f5d925ef987bbb586879b2e6.png\" alt=\"\"/></p>"}]'::jsonb, 'C', null, null, null, 'C') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-matematika-sma-012', 'sub-matematika-sma', 'top-matematika-sma-12', 'st-matematika-sma-02', 'category', 'Aljabar', 'html', null, '<p>Mirna akan memproduksi dua jenis kue dengan modal Rp8.000.000,00. Biaya produksi kue bolu sebesar Rp15.000,00 per kotak dan dijual dengan laba 40%. Sedangkan biaya produksi kue brownies sebesar Rp20.000,00 per kotak dan dijual dengan laba 35%. Setiap harinya, Mirna dapat memproduksi paling banyak 500 kotak kue.</p><p>Apabila Mirna ingin memperoleh keuntungan maksimum, tentukan<br/>Benar atau Salah untuk setiap pernyataan berikut!</p>', null, null, null, null, '[{"key":"benar","label":"Benar"},{"key":"salah","label":"Salah"}]'::jsonb, '[{"id":"A","text":"<p>Mirna harus memproduksi 200 kotak kue bolu.</p>","correctCategoryKey":"salah"},{"id":"B","text":"<p>Mirna harus memproduksi kue brownies lebih banyak.</p>","correctCategoryKey":"salah"},{"id":"C","text":"<p>Keuntungan maksimum yang dapat diperoleh Mirna adalah Rp3.100.000,00.</p>","correctCategoryKey":"benar"}]'::jsonb, 'Pernyataan A. Salah B. Salah C. Benar') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-matematika-sma-013', 'sub-matematika-sma', 'top-matematika-sma-13', null, 'category', 'Memahami, mengaplikasikan, bernalar yang lebih dan tinggi untuk menyelesaikan permasalahan terkait hubungan dua sudut, dua garis, dan dua bidang', 'html', null, '<p><img src="/soal/65502_c1f1ffe270f76a3a1535bde803228b4d.png" alt=""/></p><p>Tentukan Benar atau Salah untuk setiap pernyataan berikut terkait dengan besar sudut pada trapesium 𝐴𝐵𝐶𝐷! </p>', null, null, null, null, '[{"key":"benar","label":"Benar"},{"key":"salah","label":"Salah"}]'::jsonb, '[{"id":"A","text":"<p><img src=\"/soal/65502_3a1a1a2f9ce77db7f1cac78b777aeac3.png\" alt=\"\"/></p>","correctCategoryKey":"benar"},{"id":"B","text":"<p><img src=\"/soal/65502_288dbf2e00b1bddebeddf4aa378cf706.png\" alt=\"\"/></p>","correctCategoryKey":"benar"},{"id":"C","text":"<p><img src=\"/soal/65502_9f675a63ab39ad85502209c54a02a18f.png\" alt=\"\"/></p>","correctCategoryKey":"salah"}]'::jsonb, 'Pernyataan A. Benar B. Benar C. Salah') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-matematika-sma-014', 'sub-matematika-sma', 'top-matematika-sma-14', null, 'single', 'Geometri dan Pengukuran (Materi) Pengukuran (Submateri) Memahami, mengaplikasikan, bernalar yang lebih dan tinggi untuk enyelesaikan permasalahan terkait keliling dan luas bangun datar', 'html', null, '<p><img src="/soal/67107_be11e2276f265c5b6e2674d8ba2d2c3d.png" alt=""/></p><p>Putuskan apakah dengan tambahan informasi Pernyataan (1) dan <br/>Pernyataan (2) berikut cukup untuk menjawab pertanyaan tersebut!<br/>(1) Luas trapesium ABCD = 24. <br/>(2) BC = 10 dan CD = 5.</p>', null, '[{"key":"A","text":"<p>Pernyataan (1) SAJA cukup untuk menjawab pertanyaan, tetapi Pernyataan (2) SAJA tidak cukup. </p>"},{"key":"B","text":"<p>Pernyataan (2) SAJA cukup untuk menjawab pertanyaan, tetapi Pernyataan (1) SAJA tidak cukup.</p>"},{"key":"C","text":"<p>DUA pernyataan BERSAMA-SAMA cukup untuk menjawab pertanyaan, tetapi SATU pernyataan SAJA tidak cukup.</p>"},{"key":"D","text":"<p>Pernyataan (1) SAJA cukup untuk menjawab pertanyaan dan Pernyataan (2) SAJA cukup.</p>"},{"key":"E","text":"<p>Pernyataan (1) dan Pernyataan (2) tidak cukup untuk menjawab pertanyaan.</p>"}]'::jsonb, 'B', null, null, null, 'B') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-matematika-sma-015', 'sub-matematika-sma', 'top-matematika-sma-07', null, 'single', 'Memahami, mengaplikasikan, dan bernalar yang lebih tinggi untuk menyelesaikan permasalahan terkait Perbandingan trigonometri (sinus, kosinus, tangen, kotangen, sekan, kosekan)', 'html', null, '<p>Suatu tangga dengan panjang 6 meter disandarkan pada dinding vertikal. Sudut yang dibentuk tangga dengan lantai adalah 60°.</p><p><img src="/soal/62066_59d3ef955657eaf8f5a160bbd6c2b198.png" alt=""/></p><p>Tinggi dinding yang disentuh ujung atas tangga adalah ....</p>', null, '[{"key":"A","text":"<p>3 meter</p>"},{"key":"B","text":"<p>3√2 meter</p>"},{"key":"C","text":"<p>3√3 meter</p>"},{"key":"D","text":"<p>4√2 meter</p>"},{"key":"E","text":"<p>4√3 meter</p>"}]'::jsonb, 'C', null, null, null, 'C') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-matematika-sma-016', 'sub-matematika-sma', 'top-matematika-sma-09', null, 'mcma', 'Data dan Peluang (Materi) Data (Submateri) Memahami, mengaplikasikan, dan bernalar yang lebih tinggi untuk menyelesaikan permasalahan terkait ukuran pemusatan dan penyebaran data tunggal dan data k', 'html', null, '<p>Rata-rata nilai ulangan 17 murid dari skala 100 adalah 83. Ada 3 murid yang mengikuti ujian susulan sehingga rata-rata nilai ulangan dari 20 murid menjadi 82.<br/></p><p>Tentukan semua pernyataan berikut yang benar terkait dengan nilai ketiga murid yang mengikuti ujian susulan! Jawaban benar lebih dari satu.</p>', null, '[{"key":"A","text":"<p>Jumlah nilai ketiga murid yang mengikuti ujian susulan adalah 229. </p>"},{"key":"B","text":"<p>Rata-rata nilai ketiga murid yang mengikuti ujian susulan lebih dari 70. </p>"},{"key":"C","text":"<p>Nilai terendah dari ketiga murid yang mengikuti ujian susulan tidak kurang dari 29. </p>"},{"key":"D","text":"<p>Nilai tertinggi dari ketiga murid yang mengikuti ujian susulan lebih dari 76. </p>"},{"key":"E","text":"<p>Jangkauan data nilai ketiga murid yang mengikuti ujian susulan lebih dari dari 72. </p>"}]'::jsonb, null, array['A','B','C','D']::text[], null, null, 'Pernyataan 1, Pernyataan 2, Pernyataan 3, dan Pernyataan 4') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-matematika-sma-017', 'sub-matematika-sma', 'top-matematika-sma-15', null, 'category', 'Memahami, mengaplikasikan, dan bernalar yang lebih tinggi untuk menyelesaikan permasalahan terkait domain, kodomain, daerah hasil (range), dan representasi fungsi linear, kuadrat, dan rasional dalam berbagai bentuk', 'html', null, '<p>Fungsi didefinisikan oleh <img src="/soal/58301_e1f215c43d145ce6d57d8f93cf319473.png" alt=""/></p><p>Tentukan <strong>Benar</strong> atau <strong>Salah</strong> pada setiap pernyataan berikut yang terkait dengan grafik fungsi <img src="/soal/58301_c7903bda280f1605697c7c1fb1509485.png" alt=""/>!</p>', null, null, null, null, '[{"key":"benar","label":"Benar"},{"key":"salah","label":"Salah"}]'::jsonb, '[{"id":"A","text":"<p>Grafik fungsi ƒ terbuka ke atas.</p>","correctCategoryKey":"benar"},{"id":"B","text":"<p>Grafik fungsi ƒ memotong garis <img src=\"/soal/33292_8a3e9977ced1021279e2043ba90da806.png\" alt=\"\"/></p>","correctCategoryKey":"salah"},{"id":"C","text":"<p>Grafik fungsi ƒ tidak melalui kuadran tiga.</p>","correctCategoryKey":"benar"}]'::jsonb, 'Pernyataan A. Benar B. Salah C. Benar') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-matematika-sma-018', 'sub-matematika-sma', 'top-matematika-sma-03', null, 'mcma', 'Memahami, mengaplikasikan, dan bernalar yang lebih tinggi untuk menyelesaikan permasalahan terkait invers fungsi dan representasinya', 'html', null, '<p>Tagihan listrik bulanan di sebuah apartemen dihitung berdasarkan jumlah energi listrik (dalam kWh) yang digunakan. Apartemen tersebut masih menggunakan meteran listrik yang berbeda dari penggunaan token.</p><p>Biaya tagihan listrik dihitung dengan rumus:<img src="/soal/44044_164f5392e1e6f44c3a774f14c12d5e37.png" alt=""/></p><p>Keterangan: </p><p><img src="/soal/44044_a8a06eb6d7abbbb34dc50b57ab3e11ad.png" alt=""/> : total tagihan listrik (dalam rupiah)</p><p><img src="/soal/44044_8942e852504e3643bf634c418ea22ebe.png" alt=""/> : jumlah pemakaian energi listrik (kwh)</p><p>Andi merupakan salah satu penghuni apartemen tersebut yang menerima tagihan pembayaran listrik seperti terlihat pada gambar berikut:</p><p><img src="/soal/44044_e631f09a579b3dc314ca01f2f776555c.png" alt=""/></p><p>Dia menyadari bahwa penggunaan listrik sebulan terakhir lebih dari penggunaan listrik biasanya.</p><p>Berdasarkan informasi tersebut, biasanya berapa besar penggunaan listrik di apartemen Andi?</p><p>Pilihlah jawaban yang benar! Jawaban benar lebih dari satu.</p>', null, '[{"key":"A","text":"<p>85 kWh</p>"},{"key":"B","text":"<p>90 kWh</p>"},{"key":"C","text":"<p>100 kWh</p>"},{"key":"D","text":"<p>120 kWh</p>"},{"key":"E","text":"<p>137 kWh</p>"}]'::jsonb, null, array['A','B']::text[], null, null, 'A dan B') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-matematika-sma-019', 'sub-matematika-sma', 'top-matematika-sma-16', null, 'category', 'Memahami, mengaplikasikan, dan bernalar yang lebih tinggi untuk menyelesaikan permasalahan terkait transformasi geometri (translasi, refleksi, rotasi, dan dilatasi, serta komposisinya) dari titik', 'html', null, '<p>Pak Andi akan mempresentasikan desain gedung berukuran 60 cm × 60 cm menggunakan proyektor ke layar berukuran 2,4 meter × 1,8 meter yang dipasang di depan ruang rapat (orientasi horizontal). Proyektor menghasilkan pembesaran proporsional tergantung jaraknya dari layar.</p><p>Pak Andi menempatkan proyektor dengan jarak yang menghasilkan skala pembesaran seperti terlihat pada gambar berikut:</p><p><img src="/soal/10404_f9c9ac794c654d40d2df88cf5ad4c586.png" alt=""/></p><p>Bagaimanakah tampilan desain gedung di layar?</p><p>Tentukan <strong>Benar</strong> atau <strong>Salah</strong> pada setiap pernyataan berikut!</p>', null, null, null, null, '[{"key":"benar","label":"Benar"},{"key":"salah","label":"Salah"}]'::jsonb, '[{"id":"A","text":"<p>Perbandingan ukuran tampilan desain di layar adalah 1 : 1.</p>","correctCategoryKey":"benar"},{"id":"B","text":"<p>Ukuran panjang dan lebar tampilan desain pada layar adalah lebih dari 1 meter.</p>","correctCategoryKey":"benar"},{"id":"C","text":"<p>Terdapat bagian gambar asli desain yang terpotong dalam tampilan pada layar.</p>","correctCategoryKey":"salah"}]'::jsonb, 'Pernyataan A. Benar B. Benar C. Salah') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-matematika-sma-020', 'sub-matematika-sma', 'top-matematika-sma-17', null, 'single', 'Memahami, mengaplikasikan, dan bernalar yang lebih tinggi untuk menyelesaikan permasalahan terkait aturan pencacahan (aturan penjumlahan, aturan perkalian, permutasi, dan kombinasi)', 'html', null, '<p>Luki adalah panitia bazar di sekolahnya. Dia mendapat tugas dari ketua pelaksana untuk membuat kupon. Dia ingin di setiap kupon memiliki kode akses yang unik. Kode akses kupon bazar itu memiliki lima karakter dengan format sebagai berikut:</p><p><img src="/soal/21232_49c208306a27969b494b0ae6af1cdaab.png" alt=""/></p><p>dengan A, B, dan C menyatakan huruf, serta X dan Y menyatakan angka. Tidak boleh ada angka dan huruf yang diulang. Berapakah berapa banyak kode akses berbeda yang dapat dibuat?</p>', null, '[{"key":"A","text":"<p>1.263.600</p>"},{"key":"B","text":"<p>1.352.000</p>"},{"key":"C","text":"<p>1.404.000</p>"},{"key":"D","text":"<p>1.423.656</p>"},{"key":"E","text":"<p>1.757.600</p>"}]'::jsonb, 'C', null, null, null, 'C') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
